INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Benötigt ein Display dieser Art immer eine Hintergrundbeleuchtung?', 2, '[{"text": "Nein", "correct": true, "because": "Selbstleuchtende Pixel"}, {"text": "Ja", "correct": false, "because": "Unterschied zu LCD"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil dieser Technologie in Smartphones?', 3, '[{"text": "Hoher Kontrast", "correct": true, "because": "Tiefes Schwarz durch Pixelabschaltung"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Displaymerkmal"}, {"text": "Schnelle Installation", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen diese Displays besonders?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Ermöglicht gebogene Bildschirme"}, {"text": "Energieeffizienz", "correct": true, "because": "Nur aktive Pixel verbrauchen Strom"}, {"text": "Hohe Latenz", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Feste Struktur", "correct": false, "because": "Weniger vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Diese Technologie nutzt organische Materialien. b) Sie ist immer günstiger als LCD.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist oft teurer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines solchen Displays?', 4, '[{"text": "Bildqualität", "correct": false, "because": "Entscheidend für Anwendung"}, {"text": "Lebensdauer", "correct": false, "because": "Wichtig für Haltbarkeit"}, {"text": "Tastaturkompatibilität", "correct": true, "because": "Irrelevant für Displays"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Displays für Beleuchtung geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Flächenbeleuchtung möglich"}, {"text": "Nein", "correct": false, "because": "Auch für Licht genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist für die Bildqualität entscheidend?', 3, '[{"text": "Pixelabschaltung", "correct": true, "because": "Ermöglicht tiefes Schwarz"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Displayfaktor"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von dieser Technologie?', 5, '[{"text": "Smartphones", "correct": true, "because": "Hohe Farbtreue"}, {"text": "Fernseher", "correct": true, "because": "Große Kontraste"}, {"text": "Serverkonfiguration", "correct": false, "because": "Kein Displayzweck"}, {"text": "Netzwerkswitches", "correct": false, "because": "Andere Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Solche Displays haben schnelle Reaktionszeiten. b) Sie sind unempfindlich gegen Feuchtigkeit. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist problematisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Einsatz eines solchen Displays?', 4, '[{"text": "Kompatible Hardware", "correct": false, "because": "Notwendig für Ansteuerung"}, {"text": "Stromversorgung", "correct": false, "because": "Essenziell"}, {"text": "Mechanische Tastatur", "correct": true, "because": "Kein Displaybedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Displays immer transparent?', 2, '[{"text": "Nein", "correct": true, "because": "Transparenz ist optional"}, {"text": "Ja", "correct": false, "because": "Meist opak"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung gibt es bei der Nutzung solcher Displays?', 4, '[{"text": "Burn-In-Risiko", "correct": true, "because": "Statische Bilder problematisch"}, {"text": "Geringe Auflösung", "correct": false, "because": "Hohe Auflösungen möglich"}, {"text": "Hoher Speicherbedarf", "correct": false, "because": "Nicht displaybezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Displays immer teurer als LCD sind. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Produktion oft kostspieliger"}, {"text": "Nein", "correct": false, "because": "Preisvorteil selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines solchen Bildschirms?', 3, '[{"text": "Farbgenauigkeit", "correct": true, "because": "Fördert Bildqualität"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "CPU-spezifisch"}, {"text": "Manuelle Updates", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Solche Displays können flexibel sein. b) Sie benötigen immer Glas als Substrat.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) erlaubt auch Kunststoff"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet diese Technologie?', 5, '[{"text": "Tiefes Schwarz", "correct": true, "because": "Pixel können ausgeschaltet werden"}, {"text": "Breite Blickwinkel", "correct": true, "because": "Keine Farbverzerrung"}, {"text": "Hohe Latenz", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Feste Form", "correct": false, "because": "Flexibilität ist Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Integration solcher Displays unwichtig?', 3, '[{"text": "Stromverbrauch", "correct": false, "because": "Wichtig für Effizienz"}, {"text": "Auflösung", "correct": false, "because": "Bestimmt Klarheit"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Displays nur für kleine Geräte geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für TVs genutzt"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Displays empfindlich für hohe Temperaturen sind?', 2, '[{"text": "Ja", "correct": true, "because": "Kann Lebensdauer reduzieren"}, {"text": "Nein", "correct": false, "because": "Temperatur ist Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu dieser Technologie?', 4, '[{"text": "High-End-Fernseher", "correct": true, "because": "Nutzt Kontrast und Farben"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Kein Displayzweck"}, {"text": "Serverwartung", "correct": false, "because": "Andere Prioritäten"}]');
